(window.webpackJsonp=window.webpackJsonp||[]).push([[5],{97:function(e){e.exports=JSON.parse('{"metadata":{"timed":true,"story ID":"2db637c2-d21f-4bb2-b91a-603476e4bb8d","title":{"_default":"AAHP 621 Emily Williams 9-21-2018"},"media":{"audio":"","video":"https://www.youtube.com/watch?v=YumzspzNucY"},"languages":[],"date_created":"","date_uploaded":"3/19/2026","source":{"_default":""},"description":"","genre":"","author":"","glosser":"","speakers":[],"xml_file_name":"AAHP 621 Emily Williams 9-21-2018.eaf","source_filetype":"ELAN","tier IDs":{"Speaker 0":{"subdivided":false},"Speaker 2":{"subdivided":false},"Speaker 1":{"subdivided":false}},"speaker IDs":{"S1":{"tier":"Speaker 0"},"S2":{"tier":"Speaker 2"},"S3":{"tier":"Speaker 1"}}},"sentences":[{"speaker":"S1","tier":"Speaker 0","start_time_ms":0,"end_time_ms":22000,"num_slots":1,"text":"All right, we\'re recording. So my name is Kenna Drayton and I\'m here with Ms. Emily Williams. I\'m a part of the oral history program at the University of Florida with the African American History Project. Will you introduce us to you? To you please give us your name.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":22000,"end_time_ms":25000,"num_slots":1,"text":"My name is Ms. Emily J. Williams.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":25000,"end_time_ms":27000,"num_slots":1,"text":"J stands for","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":27000,"end_time_ms":29000,"num_slots":1,"text":"June.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":29000,"end_time_ms":33000,"num_slots":1,"text":"How did you get your name?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":33000,"end_time_ms":36000,"num_slots":1,"text":"My mother and grandmother name.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":36000,"end_time_ms":41000,"num_slots":1,"text":"Okay. When and where were you born?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":41000,"end_time_ms":47000,"num_slots":1,"text":"I was born 1946 in Hastings, Florida.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":47000,"end_time_ms":51000,"num_slots":1,"text":"Were you born to a midwife or at a hospital?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":51000,"end_time_ms":53000,"num_slots":1,"text":"A midwife.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":53000,"end_time_ms":58000,"num_slots":1,"text":"Okay. Who are your parents?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":58000,"end_time_ms":64000,"num_slots":1,"text":"Mr. And Mrs. Walter Mccarin.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":64000,"end_time_ms":67000,"num_slots":1,"text":"You know where they were born?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":67000,"end_time_ms":70000,"num_slots":1,"text":"In Georgia.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":70000,"end_time_ms":74000,"num_slots":1,"text":"You know what they did for a living?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":74000,"end_time_ms":81000,"num_slots":1,"text":"Farm? Labor.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":81000,"end_time_ms":88000,"num_slots":1,"text":"Okay. Who are your siblings?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":88000,"end_time_ms":89000,"num_slots":1,"text":"My children.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":89000,"end_time_ms":91000,"num_slots":1,"text":"Your siblings?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":91000,"end_time_ms":93000,"num_slots":1,"text":"Not my children, right? Mm-hmm","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":93000,"end_time_ms":97000,"num_slots":1,"text":"<affirmative>. Your who? Brothers and sisters. Your brothers and sisters.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":97000,"end_time_ms":98000,"num_slots":1,"text":"Who are they? What their names? Mm-hmm","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":98000,"end_time_ms":102000,"num_slots":1,"text":"<affirmative>.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":102000,"end_time_ms":117000,"num_slots":1,"text":"Okay. My older sister name is Larissa Ula. Carrie, Linda, and Deborah.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":117000,"end_time_ms":127000,"num_slots":1,"text":"Okay. Can you gimme the address of your home where you all grew up?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":127000,"end_time_ms":129000,"num_slots":1,"text":"We moved different places.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":129000,"end_time_ms":132000,"num_slots":1,"text":"Okay. Around Highton?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":132000,"end_time_ms":154000,"num_slots":1,"text":"Yeah. We live at East Hass first, and then we moved to, uh, the address of Wal McCormick Road, near the county lane.","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":154000,"end_time_ms":158000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":158000,"end_time_ms":162000,"num_slots":1,"text":"Of Putnam and St. John County.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":162000,"end_time_ms":166000,"num_slots":1,"text":"So right in between St. Augustine and Pal Laca.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":166000,"end_time_ms":175000,"num_slots":1,"text":"Mm-hmm <affirmative>. It\'s, it\'s on the, it mostly like was on the county line. Lived on the county line like Putnam and St. John County. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":175000,"end_time_ms":184000,"num_slots":1,"text":"Did you see a lot of officials traveling, living between St. Augustine and","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":184000,"end_time_ms":187000,"num_slots":1,"text":"<inaudible>? Yes.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":187000,"end_time_ms":189000,"num_slots":1,"text":"What about trains?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":189000,"end_time_ms":196000,"num_slots":1,"text":"Yes. It was a train at railroad tracks and the train came through where we left.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":196000,"end_time_ms":199000,"num_slots":1,"text":"Did you all go to the station often?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":199000,"end_time_ms":207000,"num_slots":1,"text":"It was in town Hastings. The station was located in town in the city of Hastings.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":207000,"end_time_ms":210000,"num_slots":1,"text":"Did you ever go on the train? Did you all ever?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":210000,"end_time_ms":212000,"num_slots":1,"text":"No. No.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":212000,"end_time_ms":219000,"num_slots":1,"text":"So what kind of chores did you have to do growing up, or how did you divide amongst your sisters?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":219000,"end_time_ms":239000,"num_slots":1,"text":"Uh, oh, we did field labor, house cleaning. That was <inaudible>. Whatever our hands signed to do, that\'s what we did.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":239000,"end_time_ms":243000,"num_slots":1,"text":"So who did most of the cooking?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":243000,"end_time_ms":246000,"num_slots":1,"text":"Our mom. Um,","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":246000,"end_time_ms":249000,"num_slots":1,"text":"What kind of foods did you eat?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":249000,"end_time_ms":255000,"num_slots":1,"text":"Different kind, whatever she cooked, that\'s what we ate.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":255000,"end_time_ms":258000,"num_slots":1,"text":"And that was from your own garden?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":258000,"end_time_ms":274000,"num_slots":1,"text":"Well, dad always had the vegetables in the, at the back of the house and he had a field with all different types of vegetables. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":274000,"end_time_ms":280000,"num_slots":1,"text":"Was there a separate shopping store for black people in Hastings?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":280000,"end_time_ms":284000,"num_slots":1,"text":"It was stores and hasten grocery stores And shopping stores","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":284000,"end_time_ms":289000,"num_slots":1,"text":"That were segregated?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":289000,"end_time_ms":292000,"num_slots":1,"text":"Yes. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":292000,"end_time_ms":297000,"num_slots":1,"text":"How was shopping? What was a normal shopping trip like?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":297000,"end_time_ms":309000,"num_slots":1,"text":"It was nice. I enjoyed it. Okay. Because I went a lot with my grandmother. Mm-hmm <affirmative>. She took me with her a lot. It was a grocery store.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":309000,"end_time_ms":312000,"num_slots":1,"text":"You remember the name of the store?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":312000,"end_time_ms":347000,"num_slots":1,"text":"Um, Lovett\'s and was the grocery stove. And the dressing stove was the five and 10 cent store. And they had another stove. Um, was Miss Carli store and they stole, they called the five intensive store.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":347000,"end_time_ms":349000,"num_slots":1,"text":"What was sold there?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":349000,"end_time_ms":357000,"num_slots":1,"text":"Um, well, so they can buy any, in every little thing in there like for houseware and stuff like that.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":357000,"end_time_ms":367000,"num_slots":1,"text":"Okay. What was it like going downtown? Was it kind of busy or was it kind of slow?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":367000,"end_time_ms":382000,"num_slots":1,"text":"I called it different season when it was, um, harvesting time for potatoes. It was very busy and cabbage season was very busy.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":382000,"end_time_ms":385000,"num_slots":1,"text":"So you saw a lot of people come into town for that? Yes.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":385000,"end_time_ms":386000,"num_slots":1,"text":"Mm-hmm <affirmative>. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":386000,"end_time_ms":392000,"num_slots":1,"text":"Um, so you, you say you went a lot of time to the store with your grandmother. Mm-hmm <affirmative>. What was her name?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":392000,"end_time_ms":396000,"num_slots":1,"text":"Her name was Emily. Okay. Emily Dean.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":396000,"end_time_ms":405000,"num_slots":1,"text":"So did, uh, your granddad, your dad, Walter McCormick, did he do a lot more of the selling and growing of the food?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":405000,"end_time_ms":421000,"num_slots":1,"text":"He, um, he had his own, um, produce and every other stores also, uh, the produce places to buy produce also.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":421000,"end_time_ms":424000,"num_slots":1,"text":"So he had like a stand or a store?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":424000,"end_time_ms":434000,"num_slots":1,"text":"No, he had it at the house and he would just like raise it and just like, give it away. He didn\'t know sell it. He would just raise it and give it away.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":434000,"end_time_ms":438000,"num_slots":1,"text":"So people kinda looked for him to do a good thing. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":438000,"end_time_ms":441000,"num_slots":1,"text":"Good deal. That\'s what he did.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":441000,"end_time_ms":451000,"num_slots":1,"text":"Was there ever any type of, uh, intimidation from like the white community with them being so nice and helping the blacks?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":451000,"end_time_ms":468000,"num_slots":1,"text":"Everybody Mostly like, gotten along together. It was community thing. It was nice. Everyone did what they\'re supposed to do, tend to their own business. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":468000,"end_time_ms":474000,"num_slots":1,"text":"Um, so about how old were you when you kind of realized you were black?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":474000,"end_time_ms":480000,"num_slots":1,"text":"Um, I was not one.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":480000,"end_time_ms":481000,"num_slots":1,"text":"Really?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":481000,"end_time_ms":482000,"num_slots":1,"text":"Mm-hmm.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":482000,"end_time_ms":486000,"num_slots":1,"text":"What did it mean? Hmm? What did it mean?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":486000,"end_time_ms":498000,"num_slots":1,"text":"What did it mean? Mm-hmm <affirmative>. I was just happy. I was always a happy little girl. I Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":498000,"end_time_ms":511000,"num_slots":1,"text":"So you were aware of being black, but were you aware of like, racism? Did it kinda make you nervous or anything?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":511000,"end_time_ms":527000,"num_slots":1,"text":"Not really. Just love to communicate and talk with people, but we, how I am now, it\'s like that from a little girl.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":527000,"end_time_ms":528000,"num_slots":1,"text":"Just talk and approach people","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":528000,"end_time_ms":532000,"num_slots":1,"text":"And just, yes. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":532000,"end_time_ms":536000,"num_slots":1,"text":"So segregation as a child wasn\'t really too hard? It just","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":536000,"end_time_ms":544000,"num_slots":1,"text":"Was, it was just, just normal. \'cause I just love to talk and you see people and talk with them.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":544000,"end_time_ms":545000,"num_slots":1,"text":"So you didn\'t let it be a barrier?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":545000,"end_time_ms":547000,"num_slots":1,"text":"No.","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":547000,"end_time_ms":549000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":549000,"end_time_ms":555000,"num_slots":1,"text":"So what kind of, um, where did you all play? What kind of things did you all do growing up in the neighborhood?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":555000,"end_time_ms":560000,"num_slots":1,"text":"Um, we played games.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":560000,"end_time_ms":563000,"num_slots":1,"text":"Was it a very close neighborhood or was it kind of spread out?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":563000,"end_time_ms":574000,"num_slots":1,"text":"It was kind of knitted, like, you know, \'cause we all had to go to school together and all that, so it\'s nice.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":574000,"end_time_ms":576000,"num_slots":1,"text":"Okay. And what school did you go to?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":576000,"end_time_ms":578000,"num_slots":1,"text":"Walter E. Harris High School.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":578000,"end_time_ms":581000,"num_slots":1,"text":"And how did you get to school every day?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":581000,"end_time_ms":587000,"num_slots":1,"text":"Bus. A bus? Mm-hmm <affirmative>. School, bus.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":587000,"end_time_ms":591000,"num_slots":1,"text":"What kind of route did you take?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":591000,"end_time_ms":599000,"num_slots":1,"text":"All through the woods and everywhere they had to pick the kids up. It was all in the, into the woods to pick the kids up.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":599000,"end_time_ms":603000,"num_slots":1,"text":"Was it a long bus ride? Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":603000,"end_time_ms":611000,"num_slots":1,"text":"Yes. It was pretty long. \'cause we had to go out and go the woods to, to get the kids, to get \'em to school.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":611000,"end_time_ms":616000,"num_slots":1,"text":"So where are some kids from St. Augustine? Or was it mostly, um, people coming from?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":616000,"end_time_ms":621000,"num_slots":1,"text":"It was like, it was mostly the people in the surrounding area of pacings.","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":621000,"end_time_ms":622000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":622000,"end_time_ms":624000,"num_slots":1,"text":"Would that be like spuds and,","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":624000,"end_time_ms":629000,"num_slots":1,"text":"Yes. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":629000,"end_time_ms":632000,"num_slots":1,"text":"So who are some of your teachers?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":632000,"end_time_ms":655000,"num_slots":1,"text":"Um, Ms. Rosa Hawkins, Ms. Lucy Carter, Ms. Aretha, Mary and Mr. Lawrence. Mr. James Campbell. Let\'s see, uh, coach Henderson.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":655000,"end_time_ms":657000,"num_slots":1,"text":"Were they all black?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":657000,"end_time_ms":666000,"num_slots":1,"text":"Ms. Cory Harrison? Yes. They were all black. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":666000,"end_time_ms":669000,"num_slots":1,"text":"Did you go there for all 12 years?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":669000,"end_time_ms":671000,"num_slots":1,"text":"Yes, I attended.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":671000,"end_time_ms":672000,"num_slots":1,"text":"In kindergarten?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":672000,"end_time_ms":673000,"num_slots":1,"text":"Yes.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":673000,"end_time_ms":680000,"num_slots":1,"text":"About how long was your school year? How long were you in school?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":680000,"end_time_ms":685000,"num_slots":1,"text":"Uh, first through 12th grade.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":685000,"end_time_ms":691000,"num_slots":1,"text":"And what role did school play in your community?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":691000,"end_time_ms":709000,"num_slots":1,"text":"It played a great deal because back then teachers believed in you learning. You had to learn. You didn\'t go to school every day just to sit around and play. You went to school to learn. They actually taught you,","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":709000,"end_time_ms":713000,"num_slots":1,"text":"When you say learn, it sounds like you\'re talking about more than just reading and writing.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":713000,"end_time_ms":734000,"num_slots":1,"text":"Right? You had like homemaking and you had like, um, they had like the, the gathering of the, um, the, the vegetables. You had to like clean those and get \'em prepared to go into the freezer. Yeah. We did all","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":734000,"end_time_ms":738000,"num_slots":1,"text":"That at home. Like preparing and mm-hmm <affirmative>. Organizing things and,","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":738000,"end_time_ms":741000,"num_slots":1,"text":"Right. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":741000,"end_time_ms":744000,"num_slots":1,"text":"Did you use some of those skills when you started to work?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":744000,"end_time_ms":764000,"num_slots":1,"text":"Oh, sure. I really knew. I already knew how, \'cause my mom and dad had already taught us how to work and we already knew what to do. Mm-hmm <affirmative>. It didn\'t come hard. You already knew what to do.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":764000,"end_time_ms":768000,"num_slots":1,"text":"So you, you kind of felt like","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":768000,"end_time_ms":770000,"num_slots":1,"text":"I,","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":770000,"end_time_ms":774000,"num_slots":1,"text":"That was what\'s expected of you. Like I already know how to do these things.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":774000,"end_time_ms":781000,"num_slots":1,"text":"Yes. You did whatever it took to get the job done.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":781000,"end_time_ms":787000,"num_slots":1,"text":"So what were some of your first jobs?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":787000,"end_time_ms":798000,"num_slots":1,"text":"Cleaning house, cooking, making your bed. Oh, raking yards. Cutting wood. You did all of that.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":798000,"end_time_ms":799000,"num_slots":1,"text":"You cut wood?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":799000,"end_time_ms":814000,"num_slots":1,"text":"Yes. What\'s the ax for the, the heater. You had to have wood to go in the heater. You had to pump your water with the pump. Pump water. Yes. You had to do all of that.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":814000,"end_time_ms":816000,"num_slots":1,"text":"And about how much did you get paid?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":816000,"end_time_ms":821000,"num_slots":1,"text":"No, you didn\'t really get paid. Those was your daily house charge jobs.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":821000,"end_time_ms":822000,"num_slots":1,"text":"Oh, for your house?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":822000,"end_time_ms":828000,"num_slots":1,"text":"Yes. At home. You had to do all of that at home. At home, yes.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":828000,"end_time_ms":830000,"num_slots":1,"text":"Before you even went out to work?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":830000,"end_time_ms":840000,"num_slots":1,"text":"Yes. Yes. Well, we did field labor too, but these was regular around the house. You had to do all of that at home.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":840000,"end_time_ms":841000,"num_slots":1,"text":"You had to do homework.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":841000,"end_time_ms":848000,"num_slots":1,"text":"Yes. You had every day. That wasn\'t a one time thing. That was a everyday thing. So","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":848000,"end_time_ms":853000,"num_slots":1,"text":"What would you do to take a break? Mm-hmm <affirmative>. How would you kind of relax?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":853000,"end_time_ms":865000,"num_slots":1,"text":"Well, you would rest a little bit, but you go right back to the job. Right back to the grinding pole. Because Rosalie didn\'t play. My mom didn\'t play the radio with you.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":865000,"end_time_ms":867000,"num_slots":1,"text":"So she was very stern and making sure you did your","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":867000,"end_time_ms":873000,"num_slots":1,"text":"Work. Yes. Yes. She believed in you learning","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":873000,"end_time_ms":875000,"num_slots":1,"text":"Even outside of school.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":875000,"end_time_ms":882000,"num_slots":1,"text":"She always said, you gonna know how to do more than one thing and you can rest assured you learn how to do more than one thing.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":882000,"end_time_ms":891000,"num_slots":1,"text":"So they, they settled here in Hastings? Yes. Uh, mm-hmm <affirmative>. Do you know where she went to school?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":891000,"end_time_ms":897000,"num_slots":1,"text":"Um, they used to live in Daytona. She went school in Daytona Beach.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":897000,"end_time_ms":905000,"num_slots":1,"text":"Okay. So you says that she liked for you all to do more than one thing.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":905000,"end_time_ms":913000,"num_slots":1,"text":"Yeah. Mm-hmm <affirmative>. She taught us. She said, y\'all are going to know how to do more than just one thing.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":913000,"end_time_ms":915000,"num_slots":1,"text":"So she was a teacher?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":915000,"end_time_ms":931000,"num_slots":1,"text":"Yes. And she taught us how to do all types of jobs.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":931000,"end_time_ms":933000,"num_slots":1,"text":"And what about church?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":933000,"end_time_ms":941000,"num_slots":1,"text":"Oh yeah, she attend church too. Sunday school every Sunday.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":941000,"end_time_ms":942000,"num_slots":1,"text":"What did that mean?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":942000,"end_time_ms":969000,"num_slots":1,"text":"And she would make sure that she would feed you before you leave. She would get up every Sunday morning. She would prepare baked biscuits, fried chicken, uh, cooked grits and eggs and made lemonade. And that would be your breakfast before you are off to Sunday School and church on Sunday mornings.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":969000,"end_time_ms":970000,"num_slots":1,"text":"Lemonade?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":970000,"end_time_ms":972000,"num_slots":1,"text":"Yes, lemonade.","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":972000,"end_time_ms":978000,"num_slots":1,"text":"Awesome.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":978000,"end_time_ms":984000,"num_slots":1,"text":"But so through the week, she, she did what for through for a living","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":984000,"end_time_ms":992000,"num_slots":1,"text":"Work. And the bills. Cooking, ironing, washing clothes.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":992000,"end_time_ms":995000,"num_slots":1,"text":"Did they own any of the land?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":995000,"end_time_ms":1011000,"num_slots":1,"text":"Yes, we owned at our house. That\'s what we, uh, we rented first. And then later on we had, they had Jim Walter, the build a home across the street from where we were renting. And then we moved into our house.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1011000,"end_time_ms":1014000,"num_slots":1,"text":"About how old were you then?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1014000,"end_time_ms":1022000,"num_slots":1,"text":"I would say about, about, Hmm, about eight.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1022000,"end_time_ms":1033000,"num_slots":1,"text":"Okay. So what was the holidays like? Would everyone kind of go there or would they go to great Grandma Emily\'s house?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1033000,"end_time_ms":1051000,"num_slots":1,"text":"Well, it was just at home, playing around toys, sitting around. Um, after we\'d cook, we\'d sit around and eat and talk. Just spend that Christmas together.","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":1051000,"end_time_ms":1053000,"num_slots":1,"text":"Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1053000,"end_time_ms":1054000,"num_slots":1,"text":"Open our Christmas gifts.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1054000,"end_time_ms":1058000,"num_slots":1,"text":"Did you all take any family photos?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1058000,"end_time_ms":1066000,"num_slots":1,"text":"No, we didn\'t take Mm.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1066000,"end_time_ms":1074000,"num_slots":1,"text":"Were there any type of, um, like clubs or social things in Hastings? Like a movie theater or?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1074000,"end_time_ms":1082000,"num_slots":1,"text":"No, we had TVs and go, mom did lost go into movies. We had to stay at home and watch tv.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1082000,"end_time_ms":1085000,"num_slots":1,"text":"So was there a reason why","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1085000,"end_time_ms":1100000,"num_slots":1,"text":"She just stayed? That we just had to stay home and watch the black and white tv? Should never let us go to movies. And really, if you went, you would have to travel to s Augustine or for Laca. So they didn\'t never allow, allow us to go there.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1100000,"end_time_ms":1103000,"num_slots":1,"text":"How did they find Hastings?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1103000,"end_time_ms":1119000,"num_slots":1,"text":"I don\'t really know how they really found that place. They didn\'t really, they, they just decided that they came and I guess loved it. And that\'s where they settled at? Mm-hmm <affirmative>. At mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1119000,"end_time_ms":1129000,"num_slots":1,"text":"So I know it\'s near St. Augustine. Do you remember, um, like Martin Luther King or any civil rights figures coming to St. Augustine in the sixties?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1129000,"end_time_ms":1131000,"num_slots":1,"text":"Yes. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1131000,"end_time_ms":1133000,"num_slots":1,"text":"Can you tell me about it?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1133000,"end_time_ms":1165000,"num_slots":1,"text":"Oh, it was that frightening over there because they were saying that, uh, the, the Ku Klux Klansman and all of those was over there and St. Augustine and they were like fighting and all that. When, um, Martin Luther came and Andrew Jackson and them came to ine and it was just, it was like scary to hear them talk about what was happening over there.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1165000,"end_time_ms":1167000,"num_slots":1,"text":"And So you were in Hastings?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1167000,"end_time_ms":1170000,"num_slots":1,"text":"Mm-hmm <affirmative>. About in school.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1170000,"end_time_ms":1172000,"num_slots":1,"text":"And so grade school, I was in school. Mm-hmm <affirmative>. Okay.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1172000,"end_time_ms":1175000,"num_slots":1,"text":"School then during that time,","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1175000,"end_time_ms":1180000,"num_slots":1,"text":"So you didn\'t like want to or think about doing any protesting?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1180000,"end_time_ms":1191000,"num_slots":1,"text":"Some of \'em said, I was seeing, we heard that they were doing it. But <affirmative> not in Hastings? Mm-hmm. Okay. We didn\'t have any of that out in Hastings.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1191000,"end_time_ms":1193000,"num_slots":1,"text":"Kind of just kept things quiet?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1193000,"end_time_ms":1198000,"num_slots":1,"text":"Um, yes. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1198000,"end_time_ms":1200000,"num_slots":1,"text":"Did you feel safer that way?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1200000,"end_time_ms":1212000,"num_slots":1,"text":"It was kind of frightening to hear about that, you know? Was it being near where, you know, close to where we lived? Mm-hmm <affirmative>. It was just kind of frightening.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1212000,"end_time_ms":1229000,"num_slots":1,"text":"Okay. So when did you kind of first become aware of segregation, like in grade school?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1229000,"end_time_ms":1243000,"num_slots":1,"text":"Um, during the time when we were in school, grade school, we were hearing about what was happening in st all the things. Mm-hmm <affirmative>. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1243000,"end_time_ms":1251000,"num_slots":1,"text":"Do you remember any personal experiences of racism?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1251000,"end_time_ms":1255000,"num_slots":1,"text":"Not really.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1255000,"end_time_ms":1263000,"num_slots":1,"text":"Do you remember any formal ways people fought racism? Like how black people took a stand against racism?","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":1263000,"end_time_ms":1265000,"num_slots":1,"text":"Um,","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1265000,"end_time_ms":1275000,"num_slots":1,"text":"It was just like, hear about that, you know, that were happening over there and all the things they were, people were protesting mm-hmm <affirmative>. And","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":1275000,"end_time_ms":1276000,"num_slots":1,"text":"Was","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1276000,"end_time_ms":1285000,"num_slots":1,"text":"Talking about a lot of different things that really wasn\'t, you know, right. Towards black people.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1285000,"end_time_ms":1287000,"num_slots":1,"text":"How did that make you feel?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1287000,"end_time_ms":1292000,"num_slots":1,"text":"It, um, made me feel kind of bad about it.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1292000,"end_time_ms":1298000,"num_slots":1,"text":"What helped? Did anything help?","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":1298000,"end_time_ms":1300000,"num_slots":1,"text":"Um,","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1300000,"end_time_ms":1309000,"num_slots":1,"text":"Yeah. You know, when you talk about things, it makes you feel better. When you can bring it out and talk about it, it makes you feel better.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1309000,"end_time_ms":1313000,"num_slots":1,"text":"You didn\'t do this like through a counselor. You kind of just did it with close","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1313000,"end_time_ms":1324000,"num_slots":1,"text":"Friends, right? Mm-hmm <affirmative>. Still friends and stuff like that.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1324000,"end_time_ms":1332000,"num_slots":1,"text":"So after you graduated from Walter E. Harris, how was your college, uh, application process? How did you It","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1332000,"end_time_ms":1335000,"num_slots":1,"text":"Went very good. It went good.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1335000,"end_time_ms":1337000,"num_slots":1,"text":"Where did you apply to?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1337000,"end_time_ms":1339000,"num_slots":1,"text":"Co Blanca Junior College.","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":1339000,"end_time_ms":1340000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1340000,"end_time_ms":1342000,"num_slots":1,"text":"And why that college? Well,","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1342000,"end_time_ms":1352000,"num_slots":1,"text":"I just wanted to go. I thought it was a good idea and everything and I wanted to try and go. So I did go.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1352000,"end_time_ms":1357000,"num_slots":1,"text":"Any of your other siblings went to college?","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":1357000,"end_time_ms":1362000,"num_slots":1,"text":"No. Let\'s see.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1362000,"end_time_ms":1367000,"num_slots":1,"text":"I had one.","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":1367000,"end_time_ms":1373000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1373000,"end_time_ms":1377000,"num_slots":1,"text":"What was your experience like at Collier Block?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1377000,"end_time_ms":1412000,"num_slots":1,"text":"It was a great experience. I enjoyed, uh, classes and being, uh, with the other kids and talking and discussing our classes. And I had a job working in the library mm-hmm <affirmative>. And I enjoyed it. And doing that after classes, I would go into the library and work in the library, do typing and filing books in the library. Okay. And I, that was my job and I got paid to do that.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1412000,"end_time_ms":1415000,"num_slots":1,"text":"About how much?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1415000,"end_time_ms":1430000,"num_slots":1,"text":"Hmm. Wow. It wasn\'t very much, but it kept maybe around about, I guess about three or $4 an hour or something like that.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1430000,"end_time_ms":1432000,"num_slots":1,"text":"Hmm. Were you still living at home?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1432000,"end_time_ms":1433000,"num_slots":1,"text":"Yes.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1433000,"end_time_ms":1437000,"num_slots":1,"text":"Okay. So how did you get to Collier Blocker?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1437000,"end_time_ms":1438000,"num_slots":1,"text":"Bus.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1438000,"end_time_ms":1441000,"num_slots":1,"text":"Where was Collier Blocker","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1441000,"end_time_ms":1443000,"num_slots":1,"text":"Located? In Blocker. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1443000,"end_time_ms":1448000,"num_slots":1,"text":"Mm-hmm <affirmative>. So it was about how long of a bus ride every day?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1448000,"end_time_ms":1471000,"num_slots":1,"text":"Um, it wasn\'t too long. Okay. Because I would catch the bus off at 2 0 7 and we would take, go into <inaudible> and drop the kids off. \'cause they had the bus that would run from s August Augustine to Palka? Mm-hmm <affirmative>. And from Palka back to St. Augustine, picking up students that attended Alia Blanca.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1471000,"end_time_ms":1476000,"num_slots":1,"text":"So that was a black college, a predominantly black college?","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1476000,"end_time_ms":1480000,"num_slots":1,"text":"Okay. And so was your high school?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1480000,"end_time_ms":1481000,"num_slots":1,"text":"Yes. Right.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1481000,"end_time_ms":1483000,"num_slots":1,"text":"So it wasn\'t integrated?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1483000,"end_time_ms":1484000,"num_slots":1,"text":"No.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1484000,"end_time_ms":1497000,"num_slots":1,"text":"Okay. Were you one of the first in your family to go to college? Mm. Did your mom or grandma or granddad go?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1497000,"end_time_ms":1498000,"num_slots":1,"text":"No.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1498000,"end_time_ms":1502000,"num_slots":1,"text":"Did they ever talk about school, college?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1502000,"end_time_ms":1514000,"num_slots":1,"text":"Um, no. \'cause they said they had to stop working. They had to, I stopped going to school and go to work in the work in the field. So they were around about in fifth or sixth or seventh grade,","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1514000,"end_time_ms":1517000,"num_slots":1,"text":"You didn\'t know how to read?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1517000,"end_time_ms":1537000,"num_slots":1,"text":"Um, like my grandmother, she really did. And I took up time with her and read a lot with her and stuff like that. I took up time. She was, wanted me to read to her and I would read to her. Mm-hmm <affirmative>. Yes.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1537000,"end_time_ms":1540000,"num_slots":1,"text":"Do you remember her birthdate?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1540000,"end_time_ms":1546000,"num_slots":1,"text":"Um, I believe it said her birthday was December the 24th.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1546000,"end_time_ms":1547000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1547000,"end_time_ms":1553000,"num_slots":1,"text":"Mm-hmm <affirmative>. I remember them saying that, that her birthday was Christmas Eve.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1553000,"end_time_ms":1556000,"num_slots":1,"text":"So they kind of had to stop going to school?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1556000,"end_time_ms":1559000,"num_slots":1,"text":"Yes. Because they had the birth in the fields Yes.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1559000,"end_time_ms":1560000,"num_slots":1,"text":"With their different families.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1560000,"end_time_ms":1562000,"num_slots":1,"text":"Right. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1562000,"end_time_ms":1569000,"num_slots":1,"text":"Did you hear about them talk, uh, about slavery? Any, anyone? Grandma, granddad,","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1569000,"end_time_ms":1580000,"num_slots":1,"text":"They just always talk about how they got it. Always worked, work hard.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1580000,"end_time_ms":1582000,"num_slots":1,"text":"And what kind of work do they do?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1582000,"end_time_ms":1590000,"num_slots":1,"text":"Um, field labor.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1590000,"end_time_ms":1605000,"num_slots":1,"text":"Okay. What do you remember about Desegregations in the nineties? I mean, sorry, 1970s.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1605000,"end_time_ms":1613000,"num_slots":1,"text":"Um,","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1613000,"end_time_ms":1616000,"num_slots":1,"text":"Because you were graduated outta school?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1616000,"end_time_ms":1617000,"num_slots":1,"text":"Mm-hmm","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1617000,"end_time_ms":1629000,"num_slots":1,"text":"<affirmative>. So you, did you notice it more in the community or did you hear about maybe your, your younger sisters having to go to an integrated high school or college or anything?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1629000,"end_time_ms":1648000,"num_slots":1,"text":"Um, not really. I just really found that out when, um, after I married and moved here. And how the school was, they had like the, the black school, the white school, and then they integrated some from this school and would take them uptown to the white school.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1648000,"end_time_ms":1650000,"num_slots":1,"text":"What was the name of that school?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1650000,"end_time_ms":1659000,"num_slots":1,"text":"Um, Miller Intermediate um, school. Okay. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1659000,"end_time_ms":1661000,"num_slots":1,"text":"That was in St. Augustine?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1661000,"end_time_ms":1663000,"num_slots":1,"text":"No, that was here in Crescent City.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1663000,"end_time_ms":1665000,"num_slots":1,"text":"Oh, Miller Intermediate was here. Mm-hmm","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1665000,"end_time_ms":1671000,"num_slots":1,"text":"<affirmative>. Yeah, I was here in Pleasant City.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1671000,"end_time_ms":1679000,"num_slots":1,"text":"What was that like? Was that something that you, you all talked about?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1679000,"end_time_ms":1698000,"num_slots":1,"text":"Well, um, I used to like see the kids, um, like when the buses, like have the kids on the bus. I used to go see that. Mm-hmm <affirmative>. Mm-hmm <affirmative>. Since I was, you know, was living here in the sixties.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1698000,"end_time_ms":1703000,"num_slots":1,"text":"How was the climate here in Crescent City? Was it different than Hastings?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1703000,"end_time_ms":1706000,"num_slots":1,"text":"Um, it was about the same. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1706000,"end_time_ms":1711000,"num_slots":1,"text":"Mm-hmm <affirmative>. So there was like black shops here, A black community here?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1711000,"end_time_ms":1729000,"num_slots":1,"text":"Yeah, they have this, they still had the school separated, the blacks out here and the whites was uptown and that\'s how they had it. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1729000,"end_time_ms":1733000,"num_slots":1,"text":"When did you first vote?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1733000,"end_time_ms":1736000,"num_slots":1,"text":"When I turned 18.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1736000,"end_time_ms":1740000,"num_slots":1,"text":"You remember who was running on the ballot?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1740000,"end_time_ms":1752000,"num_slots":1,"text":"I don\'t remember. Um, it was actually running then, but I voted. I had already registered to vote.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1752000,"end_time_ms":1758000,"num_slots":1,"text":"Was that experience challenging or was it pretty easy?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1758000,"end_time_ms":1762000,"num_slots":1,"text":"It was okay. It was okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1762000,"end_time_ms":1771000,"num_slots":1,"text":"Okay. Did your parents talk about voting or the importance of voting?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1771000,"end_time_ms":1779000,"num_slots":1,"text":"Yeah, they talked about it and seeing how important it was. Mm-hmm <affirmative>. To vote.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1779000,"end_time_ms":1782000,"num_slots":1,"text":"Did they hold any high positions in the community?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1782000,"end_time_ms":1815000,"num_slots":1,"text":"Um, not really. They just was like church parent people and Christian people. And they always tried to help see out the people in the community. Mom would cook and, and, um, have Dad. Dad would go and get the people and bring \'em to the house and feed them. Mm-hmm <affirmative>. They really community workers and helpers that helped people that were in need. Mm-hmm <affirmative>. Yes, they did that. They,","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1815000,"end_time_ms":1818000,"num_slots":1,"text":"Yeah. Get that water.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1818000,"end_time_ms":1826000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1826000,"end_time_ms":1831000,"num_slots":1,"text":"I think I asked you if anyone else had been to college before you, right?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1831000,"end_time_ms":1833000,"num_slots":1,"text":"Right. No. Mm-hmm","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1833000,"end_time_ms":1839000,"num_slots":1,"text":"<affirmative>. But did your mom or grandma or dad or grandparent want you to go to college?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1839000,"end_time_ms":1842000,"num_slots":1,"text":"Yes. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1842000,"end_time_ms":1844000,"num_slots":1,"text":"How did they support you?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1844000,"end_time_ms":1846000,"num_slots":1,"text":"They gave me money.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1846000,"end_time_ms":1850000,"num_slots":1,"text":"Okay. Did you have to pay","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1850000,"end_time_ms":1851000,"num_slots":1,"text":"Encourag? Me?","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1851000,"end_time_ms":1854000,"num_slots":1,"text":"Huh? Did you have to pay per class or","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1854000,"end_time_ms":1861000,"num_slots":1,"text":"Not really? Mm-hmm <affirmative>. No, I didn\'t have to pay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1861000,"end_time_ms":1863000,"num_slots":1,"text":"So college was pretty inexpensive? It was","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1863000,"end_time_ms":1879000,"num_slots":1,"text":"Pretty, yes. Back then it was pretty much inexpensive. They really needed the students. Okay. \'cause they did have farms and they wanted the students to come so that they could use the farms that they had gotten. Mm-hmm <affirmative>. For kids to attend, to attend college.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1879000,"end_time_ms":1884000,"num_slots":1,"text":"So you went to college. Um, and what did you study?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1884000,"end_time_ms":1891000,"num_slots":1,"text":"Uh, business administration. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1891000,"end_time_ms":1893000,"num_slots":1,"text":"Around what year was this?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1893000,"end_time_ms":1898000,"num_slots":1,"text":"That was in, um, the year of 1964 and 65.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1898000,"end_time_ms":1900000,"num_slots":1,"text":"So you went for two years? Mm-hmm","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1900000,"end_time_ms":1906000,"num_slots":1,"text":"<affirmative>. Six, uh, year and a half, something like that.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1906000,"end_time_ms":1908000,"num_slots":1,"text":"And then you moved here? Mm-hmm <affirmative>. To Carson City?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1908000,"end_time_ms":1909000,"num_slots":1,"text":"Mm-hmm <affirmative>. Yes.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1909000,"end_time_ms":1911000,"num_slots":1,"text":"How was that transition?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1911000,"end_time_ms":1917000,"num_slots":1,"text":"It was nice. Okay. Mm-hmm <affirmative>. <inaudible>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1917000,"end_time_ms":1921000,"num_slots":1,"text":"Were you able to continue going to school once you moved here?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1921000,"end_time_ms":1926000,"num_slots":1,"text":"No, I didn\'t go after I had moved here, down here, I stopped going.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1926000,"end_time_ms":1928000,"num_slots":1,"text":"What did you do?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1928000,"end_time_ms":1935000,"num_slots":1,"text":"I started working. Okay. Mm-hmm <affirmative>. Yes. Haven\'t gotten a job and started working.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1935000,"end_time_ms":1938000,"num_slots":1,"text":"What kind of work was available?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1938000,"end_time_ms":1941000,"num_slots":1,"text":"Like, uh, cutting Fern","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1941000,"end_time_ms":1942000,"num_slots":1,"text":"In the sixties.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1942000,"end_time_ms":1945000,"num_slots":1,"text":"Mm-hmm <affirmative>. Yes.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1945000,"end_time_ms":1952000,"num_slots":1,"text":"Okay. And did you get paid a little bit more cut Cut and firm than working at the library or was it a different time? It","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1952000,"end_time_ms":1959000,"num_slots":1,"text":"Was d it was a little more, yeah. Earn more money. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1959000,"end_time_ms":1966000,"num_slots":1,"text":"So was it the still the same chore list of house things to be done once you kind of got a house of your own?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1966000,"end_time_ms":1968000,"num_slots":1,"text":"Yes. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1968000,"end_time_ms":1979000,"num_slots":1,"text":"Still had a lot of work to do? Yes. Okay. So how did you kind of incorporate family with work?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":1979000,"end_time_ms":1989000,"num_slots":1,"text":"It worked out pretty good \'cause I had to get a babysitter. Okay. Keep someone to watch my kids after I had \'em.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":1989000,"end_time_ms":2000000,"num_slots":1,"text":"Did you have talks with any of your children about the black history of segregation and how schools were integrated before they started school?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2000000,"end_time_ms":2004000,"num_slots":1,"text":"Um, not too much. It wasn\'t really a big problem with that","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2004000,"end_time_ms":2005000,"num_slots":1,"text":"Wasn\'t a big problem?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2005000,"end_time_ms":2008000,"num_slots":1,"text":"No, it wasn\'t really a big problem with that.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2008000,"end_time_ms":2016000,"num_slots":1,"text":"Okay. Did you talk to them just about being black in America?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2016000,"end_time_ms":2017000,"num_slots":1,"text":"Yes.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2017000,"end_time_ms":2018000,"num_slots":1,"text":"What kind of things?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2018000,"end_time_ms":2030000,"num_slots":1,"text":"Well, that\'s just to go and get, uh, get more education than what I\'ve gotten. I always instill in that, in them.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2030000,"end_time_ms":2033000,"num_slots":1,"text":"You, was that for like better opportunities?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2033000,"end_time_ms":2043000,"num_slots":1,"text":"Yes. Mm-hmm <affirmative>. Better paying jobs and stuff like that.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2043000,"end_time_ms":2051000,"num_slots":1,"text":"While you were in college, did you visit or interact with any, um, like white colleges or white students?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2051000,"end_time_ms":2053000,"num_slots":1,"text":"Not really. Mm-hmm.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2053000,"end_time_ms":2055000,"num_slots":1,"text":"Did you want to?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2055000,"end_time_ms":2065000,"num_slots":1,"text":"It didn\'t really matter. Okay. It was a big deal. Out of that,","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2065000,"end_time_ms":2069000,"num_slots":1,"text":"Were you close with some of the black professors you had in college?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2069000,"end_time_ms":2072000,"num_slots":1,"text":"Mm.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2072000,"end_time_ms":2076000,"num_slots":1,"text":"Or did they know your family or anything?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2076000,"end_time_ms":2080000,"num_slots":1,"text":"Not really. Mm-hmm. No.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2080000,"end_time_ms":2085000,"num_slots":1,"text":"Did you ever travel to like home meet, um, fam U\'s Homecoming or Bethune?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2085000,"end_time_ms":2087000,"num_slots":1,"text":"No.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2087000,"end_time_ms":2103000,"num_slots":1,"text":"Okay. Well, since integration, do you feel like the community has gotten better? Do you think there\'s been progress made since the sixties?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2103000,"end_time_ms":2111000,"num_slots":1,"text":"There\'s probably some, but it\'s a lot of more work to get done.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2111000,"end_time_ms":2119000,"num_slots":1,"text":"So what do you hope kids in the future can do or families could do?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2119000,"end_time_ms":2130000,"num_slots":1,"text":"Work more, you know, both closely together to improve things.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2130000,"end_time_ms":2132000,"num_slots":1,"text":"There some, there","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2132000,"end_time_ms":2138000,"num_slots":1,"text":"Really are. I has been, there\'s always room for improvement. Mm-hmm <affirmative>. <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2138000,"end_time_ms":2148000,"num_slots":1,"text":"So is there a, I guess a takeaway, like you always want people to know. What about you","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2148000,"end_time_ms":2152000,"num_slots":1,"text":"To know about me? Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2152000,"end_time_ms":2156000,"num_slots":1,"text":"And like your life motto or things that\'s kind of helped you get","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":2156000,"end_time_ms":2157000,"num_slots":1,"text":"Yeah,","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2157000,"end_time_ms":2173000,"num_slots":1,"text":"\'cause I love to talk to \'em a lot and discuss things, you know, and which I enjoy talking with people and being involved. I love, I enjoyed that.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2173000,"end_time_ms":2177000,"num_slots":1,"text":"What got you in the spirit of giving?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2177000,"end_time_ms":2190000,"num_slots":1,"text":"My parents, they always, they always taught us. So just a generational thing. It\'s from one generation to the other and that\'s the way we were raised that way.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2190000,"end_time_ms":2194000,"num_slots":1,"text":"Did you all go to the beach?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2194000,"end_time_ms":2202000,"num_slots":1,"text":"Yeah, it was like the special occasion, like, um, Easter, something like that. <laugh> Easter. I can remember that.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2202000,"end_time_ms":2203000,"num_slots":1,"text":"To St. Augustine?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2203000,"end_time_ms":2208000,"num_slots":1,"text":"Yeah. To um, Crescent. Beach. Crescent, yes. Easter.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2208000,"end_time_ms":2210000,"num_slots":1,"text":"About how old were you?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2210000,"end_time_ms":2224000,"num_slots":1,"text":"Uh, just around about seven or eight, something like that. Can remember that Dad and mom used to always love to take us to the beach for Easter.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2224000,"end_time_ms":2225000,"num_slots":1,"text":"I like that.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2225000,"end_time_ms":2227000,"num_slots":1,"text":"Yes.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2227000,"end_time_ms":2228000,"num_slots":1,"text":"So","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2228000,"end_time_ms":2230000,"num_slots":1,"text":"Sunday evening,","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2230000,"end_time_ms":2237000,"num_slots":1,"text":"When did you kind of realize that you were gonna grow up and I guess have a family?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2237000,"end_time_ms":2247000,"num_slots":1,"text":"Um, uh, after I turned, um, like 18, going on 19, like something like that.","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":2247000,"end_time_ms":2250000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2250000,"end_time_ms":2255000,"num_slots":1,"text":"And did you have um, or how many children?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2255000,"end_time_ms":2258000,"num_slots":1,"text":"Five. Five? Five? Yes. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2258000,"end_time_ms":2262000,"num_slots":1,"text":"Were they all delivered by midwives?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2262000,"end_time_ms":2264000,"num_slots":1,"text":"No, not all of them.","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":2264000,"end_time_ms":2268000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2268000,"end_time_ms":2279000,"num_slots":1,"text":"Was three, let\'s see, one, no, I had two delivered in the hospital. Two, three delivered in the hospital and two delivered by midwives.","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":2279000,"end_time_ms":2280000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2280000,"end_time_ms":2284000,"num_slots":1,"text":"That\'s what I have.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2284000,"end_time_ms":2288000,"num_slots":1,"text":"Do you feel like technology has gotten different or gotten better?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2288000,"end_time_ms":2291000,"num_slots":1,"text":"It\'s better.","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":2291000,"end_time_ms":2292000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2292000,"end_time_ms":2295000,"num_slots":1,"text":"Do you find it easy to use?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2295000,"end_time_ms":2316000,"num_slots":1,"text":"Yes. It\'s,","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2316000,"end_time_ms":2324000,"num_slots":1,"text":"So you did a lot of, uh, family work here and you said you were married when you moved here to Crescent City?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2324000,"end_time_ms":2327000,"num_slots":1,"text":"I got married and moved to Crescent City.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2327000,"end_time_ms":2330000,"num_slots":1,"text":"Okay. How was the courting process?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2330000,"end_time_ms":2331000,"num_slots":1,"text":"It was nice. It was Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2331000,"end_time_ms":2334000,"num_slots":1,"text":"Did he ask for your hand in marriage? Mm-hmm","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2334000,"end_time_ms":2335000,"num_slots":1,"text":"<affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2335000,"end_time_ms":2358000,"num_slots":1,"text":"Yes. To your parents? Yes. Oh, that was the custom? Yes. Okay. Okay. I feel like marriage customs maybe, maybe they\'ve changed or not. Mm-hmm <affirmative>. I think my mom said it was in the, you all announced it in the newspaper?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2358000,"end_time_ms":2365000,"num_slots":1,"text":"I dunno, it might a bit, I dunno. It\'s been so long. I don\'t know about that. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2365000,"end_time_ms":2377000,"num_slots":1,"text":"Can you tell me about this, um, moving here and like, how did you all go about meeting neighbors and talking to other people?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2377000,"end_time_ms":2386000,"num_slots":1,"text":"It was nice. I went out and met people and people in the neighborhood and talked, walked around. It was nice.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2386000,"end_time_ms":2390000,"num_slots":1,"text":"Oh, so just kind of like door to door, hey? Mm-hmm <affirmative>. Did you just","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2390000,"end_time_ms":2392000,"num_slots":1,"text":"Yeah. Whole and yeah. Mm-hmm","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2392000,"end_time_ms":2395000,"num_slots":1,"text":"<affirmative>. Do you feel like people do those things anymore?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2395000,"end_time_ms":2408000,"num_slots":1,"text":"I don\'t really know whether they still do that now or not. I don\'t know. People are so busy now. Whatever they have to do, they have to hurricane all of this. So,","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2408000,"end_time_ms":2410000,"num_slots":1,"text":"But you all made time to get to know your neighbors?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2410000,"end_time_ms":2419000,"num_slots":1,"text":"Yes. But things have changed a lot. Hmm.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2419000,"end_time_ms":2421000,"num_slots":1,"text":"But you felt like this was your home","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2421000,"end_time_ms":2431000,"num_slots":1,"text":"That you come here? Yes. Mm-hmm <affirmative>. It was nice and quiet.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2431000,"end_time_ms":2436000,"num_slots":1,"text":"So what kind of things would you all do for fun here in Casson City?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2436000,"end_time_ms":2439000,"num_slots":1,"text":"What kind? Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2439000,"end_time_ms":2443000,"num_slots":1,"text":"You all go to the river. Would you go to St. Augustine or?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2443000,"end_time_ms":2457000,"num_slots":1,"text":"I\'d go to the lake and drive down to the lakes and go out to the thrift stores and go to the stove and in the community and talk with the people and I enjoy that. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2457000,"end_time_ms":2461000,"num_slots":1,"text":"Are you a part of any community organizations?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2461000,"end_time_ms":2468000,"num_slots":1,"text":"Mm, not really. Okay.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2468000,"end_time_ms":2474000,"num_slots":1,"text":"So the church that you go to, was that the initial church? The first church you came to when you came to Scent City?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2474000,"end_time_ms":2493000,"num_slots":1,"text":"No, I used to go to, uh, Jethro. Okay. Went out there a couple of times.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2493000,"end_time_ms":2495000,"num_slots":1,"text":"So you continue to go","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2495000,"end_time_ms":2517000,"num_slots":1,"text":"Church. And then I find the other church house of God and I love bit better than the one than just, so that\'s the one I joined. Mm-hmm <affirmative>. And that\'s why I\'ve been, and I gotta be in there. Love my church.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2517000,"end_time_ms":2523000,"num_slots":1,"text":"So when, when would you go back and visit home and visit Hastings? Like","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2523000,"end_time_ms":2532000,"num_slots":1,"text":"How often? Um, probably, um, maybe in the future or something like that.","dependents":[]},{"speaker":"S3","tier":"Speaker 1","start_time_ms":2532000,"end_time_ms":2535000,"num_slots":1,"text":"I,","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2535000,"end_time_ms":2550000,"num_slots":1,"text":"I have more time \'cause I enjoy working in my community and helping people. That\'s what I do mostly here. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2550000,"end_time_ms":2554000,"num_slots":1,"text":"Do you have any funny stories from Hastings?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2554000,"end_time_ms":2589000,"num_slots":1,"text":"Um, uh, just memories. A lot of memories from with mom and dad and my sisters now and when our family gatherings and we just have a good time. Mm-hmm <affirmative>. Something about the old time. Old days and everything when we grew up and all, but all we did and now mom and dad and all the, our grandparents.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2589000,"end_time_ms":2591000,"num_slots":1,"text":"You felt like you learned a lot?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2591000,"end_time_ms":2595000,"num_slots":1,"text":"Yes. I taught you a lot Right Then","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2595000,"end_time_ms":2598000,"num_slots":1,"text":"That was like one thing that stuck with you.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2598000,"end_time_ms":2607000,"num_slots":1,"text":"Um, being raised up and spending time with my grandparents.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2607000,"end_time_ms":2609000,"num_slots":1,"text":"So spending time with family. Mm-hmm","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2609000,"end_time_ms":2612000,"num_slots":1,"text":"<affirmative>. And my family. I enjoyed that.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2612000,"end_time_ms":2614000,"num_slots":1,"text":"What did your granddad do?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2614000,"end_time_ms":2617000,"num_slots":1,"text":"He was a farmer worker right on the farm. What\'s","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2617000,"end_time_ms":2618000,"num_slots":1,"text":"His name?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2618000,"end_time_ms":2624000,"num_slots":1,"text":"His name was Emma ine.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2624000,"end_time_ms":2627000,"num_slots":1,"text":"And are they from Georgia too?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2627000,"end_time_ms":2631000,"num_slots":1,"text":"Yes. Grandparents. It was all from Georgia.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2631000,"end_time_ms":2636000,"num_slots":1,"text":"And those were the grandparents on your mom\'s side? Mm-hmm <affirmative>. Did you know grandparents on your dad\'s side?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2636000,"end_time_ms":2644000,"num_slots":1,"text":"Yes. My grandmother, she was from Georgia on my dad\'s side. What\'s her name? She was from, her name was Viola Cobb.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2644000,"end_time_ms":2647000,"num_slots":1,"text":"Okay. Did he talk about his dad?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2647000,"end_time_ms":2657000,"num_slots":1,"text":"Um, not too much about his dad. He always talked about his mom.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2657000,"end_time_ms":2659000,"num_slots":1,"text":"Did you get to meet her?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2659000,"end_time_ms":2664000,"num_slots":1,"text":"Yes. Mm-hmm <affirmative>. We used to go visit her in Georgia.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2664000,"end_time_ms":2668000,"num_slots":1,"text":"What was the trip like? Hmm? What was the trip like?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2668000,"end_time_ms":2677000,"num_slots":1,"text":"It was nice.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2677000,"end_time_ms":2680000,"num_slots":1,"text":"How\'d you travel?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2680000,"end_time_ms":2684000,"num_slots":1,"text":"Mm, i dad car.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2684000,"end_time_ms":2687000,"num_slots":1,"text":"What kind of things would she have for you all when you got there?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2687000,"end_time_ms":2692000,"num_slots":1,"text":"She would have food cooked and cakes baked.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2692000,"end_time_ms":2693000,"num_slots":1,"text":"Mm,","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2693000,"end_time_ms":2699000,"num_slots":1,"text":"Nice.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2699000,"end_time_ms":2702000,"num_slots":1,"text":"What did you do when you go there?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2702000,"end_time_ms":2714000,"num_slots":1,"text":"We would just talk and play among ourselves. Just we enjoyed seeing her. Mm-hmm <affirmative>. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2714000,"end_time_ms":2717000,"num_slots":1,"text":"So you got to travel a little bit growing up?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2717000,"end_time_ms":2718000,"num_slots":1,"text":"Yes.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2718000,"end_time_ms":2721000,"num_slots":1,"text":"And some other places you went to?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2721000,"end_time_ms":2748000,"num_slots":1,"text":"Oh, we did migrant work. We went to Delaware. What it was Virginia and Delaware. And we gathered crops through the summer. Mm-hmm <affirmative>. We all worked in the fields, picking tomatoes, beans and potatoes.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2748000,"end_time_ms":2751000,"num_slots":1,"text":"So you all were on the road for a little while? Yes. Throughout","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2751000,"end_time_ms":2754000,"num_slots":1,"text":"We traveled. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2754000,"end_time_ms":2757000,"num_slots":1,"text":"Did you like that or did you like being home?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2757000,"end_time_ms":2769000,"num_slots":1,"text":"I prefer to be home, but we had to go, we had to leave and go with our parents to do what our parents told us to do. We had to obey.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2769000,"end_time_ms":2771000,"num_slots":1,"text":"Did you wanted to do something else?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2771000,"end_time_ms":2780000,"num_slots":1,"text":"Didn\'t want to go up there. Didn\'t want to leave home. We wanted to just stay home.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2780000,"end_time_ms":2782000,"num_slots":1,"text":"And that\'s how you all made money?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2782000,"end_time_ms":2788000,"num_slots":1,"text":"Yes. We went and, and made money to pay our bills and buy our school clothes.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2788000,"end_time_ms":2791000,"num_slots":1,"text":"And who took care of the house while y\'all were away?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2791000,"end_time_ms":2794000,"num_slots":1,"text":"It was just there. I stayed there until we came back.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2794000,"end_time_ms":2797000,"num_slots":1,"text":"<laugh>,","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2797000,"end_time_ms":2801000,"num_slots":1,"text":"It\'ll be a house alone. <laugh>.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2801000,"end_time_ms":2802000,"num_slots":1,"text":"So no animals or?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2802000,"end_time_ms":2804000,"num_slots":1,"text":"No, we didn\'t have any.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2804000,"end_time_ms":2812000,"num_slots":1,"text":"Okay. Are there any other things you wanna add?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2812000,"end_time_ms":2817000,"num_slots":1,"text":"Not really.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2817000,"end_time_ms":2821000,"num_slots":1,"text":"That you can think of?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2821000,"end_time_ms":2859000,"num_slots":1,"text":"No. I just enjoy raising my children and getting them up. Grown mm-hmm <affirmative>. So that they can go their own separate ways. Mm-hmm <affirmative>. Mm-hmm <affirmative>. I enjoy raising them and talking to them and trying to instill things value into them so that when they gotten grown, they already know how to take care of themselves. Mm-hmm <affirmative>. And how to provide for themselves and take care of themselves because that\'s very important.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2859000,"end_time_ms":2873000,"num_slots":1,"text":"You feel like they face maybe, maybe your, your sons more than your daughters. Do you feel like they felt they face more challenges being like black men? Or was it hard for black men and women? Period.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2873000,"end_time_ms":2881000,"num_slots":1,"text":"It was just hard for all leaders. The men and the women.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2881000,"end_time_ms":2918000,"num_slots":1,"text":"Mm-hmm <affirmative>. And so you prepare them. Okay. Well, we can always schedule another interview, we\'ll talk about other things, but thank you for your time. Just letting me get some history of you of Hastings in Crescent City.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2918000,"end_time_ms":2921000,"num_slots":1,"text":"Thank you.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2921000,"end_time_ms":2926000,"num_slots":1,"text":"So what do you do now? Hmm? So what do you do now?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2926000,"end_time_ms":2932000,"num_slots":1,"text":"What do I do now? Mm-hmm <affirmative>. Wow. I found home in my house.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2932000,"end_time_ms":2941000,"num_slots":1,"text":"Yeah. I mean you were, you\'ve done a lot of different jobs, mom. Yes. Field worker. So what do you do now?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2941000,"end_time_ms":2969000,"num_slots":1,"text":"I\'m mostly like retired if I just want, just help in the community, that\'s what I do now. And with my feet being very ag I\'m aggravated, I can\'t get up and get out and do like I used to do. Mm-hmm <affirmative>. Like see about the people in the community. Mm-hmm <affirmative>. I enjoy, that\'s my happiness because I love people. I can\'t get up and get out like I used to and drive my car and go do things for people.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2969000,"end_time_ms":2972000,"num_slots":1,"text":"Yeah. But you\'ve been pretty healthy your whole life, right?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2972000,"end_time_ms":2977000,"num_slots":1,"text":"Yes.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":2977000,"end_time_ms":2985000,"num_slots":1,"text":"When you first were starting to go to the doctor, did you have a black physician or white or did you have a choice?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":2985000,"end_time_ms":3000000,"num_slots":1,"text":"Um, I had different ones. Okay. Both races. Black, white.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":3000000,"end_time_ms":3005000,"num_slots":1,"text":"Do you feel like medicine has advanced, it\'s made some progress compared to","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":3005000,"end_time_ms":3008000,"num_slots":1,"text":"Yes it has.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":3008000,"end_time_ms":3009000,"num_slots":1,"text":"And treatment.","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":3009000,"end_time_ms":3012000,"num_slots":1,"text":"Right.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":3012000,"end_time_ms":3015000,"num_slots":1,"text":"Did you work in the health field before?","dependents":[]},{"speaker":"S2","tier":"Speaker 2","start_time_ms":3015000,"end_time_ms":3022000,"num_slots":1,"text":"Mm, no.","dependents":[]},{"speaker":"S1","tier":"Speaker 0","start_time_ms":3022000,"end_time_ms":3025000,"num_slots":1,"text":"Okay. All righty. It is September 21st. We\'re in Cent City, Florida.","dependents":[]}]}')}}]);
